import RNA, random, time
target='((..(((((........(.((..((.(.....(....).((((((((.........((......((((.....))))......))...((..((.......(..(......)..)..((..((.....((....)).((((.....(((.....(..((.(...).))..).....))).((((...(.......(..(.((...)).)..).......)...))))........)))).....((((((...)))))).))..))...........))..)).........(..((((....))((((((.....(........).....))))))..))..)...))))))))........).))..)).).....(.......).)))))..)).'
seq=''
seq=list(seq)
N=len(seq)

# pair map for target
stack=[]
pairs=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs.append((j,i))
tpair={}
for (i,j) in pairs:
    tpair[i]=j; tpair[j]=i

def fold(s): return RNA.fold(''.join(s))[0]
def dist(s): return RNA.bp_distance(fold(s), target)

def diagnose(s):
    f=fold(s)
    # get pairs from folded
    st=[]; fpairs=[]
    for i,c in enumerate(f):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); fpairs.append((j,i))
    fpairset=set(fpairs)
    tpairset=set(pairs)
    missing=[p for p in pairs if p not in fpairset]
    spurious=[p for p in fpairs if p not in tpairset]
    return missing, spurious, f

best=seq[:]; best_d=dist(seq)
print('start', best_d)

start=time.time()
random.seed(2)
# Iterative repair loop
for iteration in range(200):
    missing, spurious, f = diagnose(seq)
    d = len(missing)+len(spurious)
    if d==0:
        print('SOLVED at iter', iteration); break
    # Break spurious pairs at unpaired-target positions -> A
    changed=False
    for (i,j) in spurious:
        if target[i]=='.':
            seq[i]='A'; changed=True
        if target[j]=='.':
            seq[j]='A'; changed=True
    # Strengthen missing pairs -> GC
    for (i,j) in missing:
        # set to GC pair
        seq[i]='G'; seq[j]='C'; changed=True
    if not changed:
        # try random perturbation at mismatched positions
        allm=set()
        for (i,j) in missing+spurious:
            allm.add(i); allm.add(j)
        for p in allm:
            if target[p]=='.':
                seq[p]=random.choice('AU')
        changed=True
    nd=dist(seq)
    if nd < best_d:
        best_d=nd; best=seq[:]
        print('iter',iteration,'d',nd)
    elif nd > best_d+5:
        # revert
        seq=best[:]
    if time.time()-start > 100:
        print('timeout'); break

print('final best dist', best_d)
print(''.join(best))
print('len', len(best))
EOF
